    }
  }

  /** 1 つの操作の失敗で、ほかの操作やアプリ全体を止めない。 */
  private fail(entry: Entry, error: unknown): void {
    if (entry.failed) return;
    entry.failed = true;
    console.error(`[itemInteractions] ${entry.interaction.id} が失敗したため、MR を始め直すまで止めます`, error);
